#!/usr/bin/env bash
# Local VM lab for the eBPF fleet repository.
#
# One command surface for disposable cloud-image VMs. Hardware
# virtualization is the normal mode; a cross-architecture image can be
# booted with QEMU TCG system emulation for a functional smoke only. The
# lab is deliberately self-contained:
#
#   * every generated byte (base images, overlays, cloud-init seeds, SSH
#     keys, logs, collected artifacts) lives under target/vm/, which is
#     gitignored, and nothing outside the repository is written;
#   * QEMU user-mode networking with an explicit 127.0.0.1 hostfwd port is
#     the only network attachment - no bridges, taps, iptables, libvirt,
#     host systemd units, or rootful Podman;
#   * no sudo and no root: a native KVM boot only needs access to /dev/kvm,
#     and an emulated boot uses the unprivileged TCG accelerator;
#   * the SSH key is ephemeral and only authorizes the throwaway guest
#     user `fleet`.
#
# Architecture and acceleration:
#
#   A native image (arch matches `uname -m`) boots with KVM: that is the
#   only mode used for performance or kernel-matrix claims. An image for
#   the other architecture boots with QEMU TCG system emulation and is
#   explicitly non-performance: it proves the ARM64 (or x86_64) userspace
#   artifact works, never a latency or throughput number. The pinned
#   `ubuntu-24.04-arm64` image on this x86_64 host is the intended TCG row.
#
#   AArch64 guests need UEFI firmware (there is no direct kernel boot for
#   the Ubuntu cloud image). The lab looks for it in this order: the
#   VM_ARM64_UEFI environment variable, target/vm/firmware/AAVMF_CODE.fd,
#   the distro paths listed in find_arm64_uefi(), and finally
#   `nix build --no-link --print-out-paths nixpkgs#edk2` under
#   share/edk2/aarch64 if a Nix store provides one. See
#   docs/runbooks/vm-lab.md for how to obtain the firmware.
#
# Usage: scripts/vm/lab.sh <command> [options]
#
# Commands:
#   bootstrap   create target/vm layout, verify/download the pinned base
#               image, generate the ephemeral SSH key (no VM boot)
#   up          create a qcow2 overlay + cloud-init seed and boot a VM
#   run         run a command inside a running VM over SSH
#   ssh         interactive SSH shell into a running VM
#   down        stop a VM and remove its overlay; --all stops every VM
#   status      show base images and instances with liveness/SSH details
#   collect     copy VM logs and a guest diagnostic bundle under target/vm
#   copy        copy one file between the host and a running VM over SSH
#
# Options:
#   --image <name>      image key from scripts/vm/images.json
#                       (default: the default_image entry, ubuntu-24.04)
#   --name <instance>   instance name, lowercase letters/digits/hyphens
#                       (default: image key with dots replaced by hyphens,
#                       so ubuntu-24.04 boots as instance ubuntu-24-04)
#   --port <port>       127.0.0.1 hostfwd port for SSH (default: first
#                       free port in 2222-2299)
#   --cpus <n>          vCPUs (default: 2, env VM_CPUS)
#   --memory <mib>      guest memory in MiB (default: 2048, env VM_MEMORY_MB)
#   --disk-size <size>  overlay virtual disk size (default: 20G)
#   --timeout <seconds> boot/SSH wait budget (default: 240, env VM_BOOT_TIMEOUT)
#   --accel <mode>      auto (default), kvm, or tcg. auto uses KVM when the
#                       image architecture matches the host and TCG when it
#                       does not; kvm rejects a cross-architecture image and
#                       tcg forces emulation for a native image (slow, for
#                       debugging only)
#   --cloud-init <p>    full (default) or lean. lean skips the guest apt
#                       package step, which is far too slow under TCG; the
#                       arm64 TCG smoke uses it and works with only the
#                       base-image userland
#   --firmware <path>   AArch64 UEFI firmware (env VM_ARM64_UEFI); only used
#                       for aarch64 images
#   --all-images        bootstrap: fetch every pinned image for this arch
#   --force             bootstrap: rewrite the cached base image
#   --all               down/collect: operate on every instance
#   --purge             down: delete the instance directory, not just state
#   --from-guest        copy: guest source -> local destination (default is
#                       local source -> guest destination)
#   --help              show this help
#
# Run inside the devenv shell so qemu, cloud-localds, openssh, jq and
# xorriso are on PATH:
#
#   devenv shell -- scripts/vm/lab.sh bootstrap
#
# On a host where only a bare Nix store has the tools, point the lab at
# their bin directories (same pattern as docs/runbooks/rootful-compose.md):
#
#   export DEV
#   export VM_LAB_TOOL_PATH=/nix/store/<qemu>/bin:/nix/store/<libisoburn>/bin
#
# Environment:
#   VM_LAB_ROOT       state root (default: <repo>/target/vm)
#   VM_LAB_TOOL_PATH  extra colon-separated PATH entries to search first
#   VM_ACCEL          override --accel (auto, kvm or tcg)
#   VM_ARM64_UEFI     path to the AArch64 UEFI firmware file
#   VM_CLOUD_INIT     override --cloud-init (full or lean)
#   VM_CPUS, VM_MEMORY_MB, VM_BOOT_TIMEOUT, VM_PORT_BASE, VM_PORT_MAX,
#   VM_SSH_USER       overrides for the matching defaults (VM_SSH_USER is
#                     fixed to fleet in the cloud-init user-data)

set -euo pipefail
shopt -s nullglob

script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"
repo_root="$(cd -- "$script_dir/../.." && pwd -P)"
vm_root="${VM_LAB_ROOT:-$repo_root/target/vm}"
images_json="$script_dir/images.json"
cloud_init_dir="$script_dir/cloud-init"
images_dir="$vm_root/images"
instances_dir="$vm_root/instances"
keys_dir="$vm_root/keys"
logs_dir="$vm_root/logs"
tmp_dir="$vm_root/tmp"
lock_file="$vm_root/lock"

kvm_dev="${KVM_DEV:-/dev/kvm}"
ssh_user="fleet"
default_image=""
image=""
name=""
port=""
cpus="${VM_CPUS:-2}"
memory_mb="${VM_MEMORY_MB:-2048}"
disk_size="20G"
boot_timeout="${VM_BOOT_TIMEOUT:-240}"
port_base="${VM_PORT_BASE:-2222}"
port_max="${VM_PORT_MAX:-2299}"
accel="${VM_ACCEL:-auto}"
cloud_init_profile="${VM_CLOUD_INIT:-full}"
arm64_uefi="${VM_ARM64_UEFI:-}"
bootstrap_all=0
force=0
down_all=0
purge=0
from_guest=0
cmd=""
run_cmd=()
pos_args=()

info() { printf 'lab: %s\n' "$*" >&2; }
warn() { printf 'lab: warning: %s\n' "$*" >&2; }
die() {
  printf 'lab: error: %s\n' "$*" >&2
  exit 1
}

usage() {
  awk 'NR > 1 { if ($0 !~ /^#/) exit; sub(/^# ?/, ""); print }' "${BASH_SOURCE[0]}"
}

acquire_lock() {
  mkdir -p "$vm_root"
  exec 9>"$lock_file"
  if ! flock -n 9; then
    info "another lab operation holds $lock_file; waiting"
    flock -w 900 9 || die "timed out waiting for the lab lock $lock_file"
  fi
}

release_lock() {
  # Keep the redirections separate: `exec 9>&- 2>/dev/null` would also
  # permanently redirect the script's own stderr to /dev/null.
  flock -u 9 2>/dev/null || true
  exec 9>&- || true
}

record_event() {
  mkdir -p "$logs_dir"
  printf '%s %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$*" >>"$logs_dir/lab.log" 2>/dev/null || true
}

# ---------------------------------------------------------------------------
# argument parsing
# ---------------------------------------------------------------------------

while (($# > 0)); do
  arg="$1"
  case "$arg" in
    -h | --help)
      usage
      exit 0
      ;;
    --image | --name | --port | --cpus | --memory | --disk-size | --timeout | --accel | --cloud-init | --firmware)
      [[ $# -ge 2 && -n "$2" ]] || die "option $arg needs a value"
      case "$arg" in
        --image) image="$2" ;;
        --name) name="$2" ;;
        --port) port="$2" ;;
        --cpus) cpus="$2" ;;
        --memory) memory_mb="$2" ;;
        --disk-size) disk_size="$2" ;;
        --timeout) boot_timeout="$2" ;;
        --accel) accel="$2" ;;
        --cloud-init) cloud_init_profile="$2" ;;
        --firmware) arm64_uefi="$2" ;;
      esac
      shift 2
      ;;
    --image=*) image="${arg#*=}"; shift ;;
    --name=*) name="${arg#*=}"; shift ;;
    --port=*) port="${arg#*=}"; shift ;;
    --cpus=*) cpus="${arg#*=}"; shift ;;
    --memory=*) memory_mb="${arg#*=}"; shift ;;
    --disk-size=*) disk_size="${arg#*=}"; shift ;;
    --timeout=*) boot_timeout="${arg#*=}"; shift ;;
    --accel=*) accel="${arg#*=}"; shift ;;
    --cloud-init=*) cloud_init_profile="${arg#*=}"; shift ;;
    --firmware=*) arm64_uefi="${arg#*=}"; shift ;;
    --all-images) bootstrap_all=1; shift ;;
    --force) force=1; shift ;;
    --all) down_all=1; shift ;;
    --purge) purge=1; shift ;;
    --from-guest) from_guest=1; shift ;;
    --)
      shift
      while (($# > 0)); do
        run_cmd+=("$1")
        shift
      done
      ;;
    -*)
      die "unknown option: $arg (try --help)"
      ;;
    *)
      if [[ -z "$cmd" ]]; then
        case "$arg" in
          bootstrap | up | run | ssh | down | status | collect | copy) cmd="$arg" ;;
          *) die "unknown command: $arg (try --help)" ;;
        esac
      elif [[ "$cmd" == "copy" ]]; then
        pos_args+=("$arg")
      else
        die "unexpected argument: $arg (put guest commands after --, see --help)"
      fi
      shift
      ;;
  esac
done

if [[ -z "$cmd" ]]; then
  usage >&2
  exit 2
fi

if ((from_guest)) && [[ "$cmd" != "copy" ]]; then
  die "--from-guest is only valid with the copy command"
fi

validate_positive_int() {
  local label="$1" value="$2"
  [[ "$value" =~ ^[0-9]+$ ]] || die "$label must be a positive integer, got '$value'"
  ((value > 0)) || die "$label must be greater than zero, got '$value'"
}

validate_instance_name() {
  local candidate="$1"
  [[ "$candidate" =~ ^[a-z0-9][a-z0-9-]{0,62}$ ]] ||
    die "instance name '$candidate' must be lowercase letters, digits and hyphens, max 63 chars"
}

case "$cpus" in '' | *[!0-9]*) die "--cpus must be a positive integer, got '$cpus'" ;; esac
[[ "$memory_mb" =~ ^[0-9]+$ ]] || die "--memory must be a positive integer, got '$memory_mb'"
[[ "$boot_timeout" =~ ^[0-9]+$ ]] || die "--timeout must be a positive integer, got '$boot_timeout'"
[[ "$disk_size" =~ ^[0-9]+[GMT]$ ]] || die "--disk-size must look like 20G, 4096M or 1T, got '$disk_size'"
case "$accel" in
  auto | kvm | tcg) ;;
  *) die "--accel must be auto, kvm or tcg, got '$accel'" ;;
esac
case "$cloud_init_profile" in
  full | lean) ;;
  *) die "--cloud-init must be full or lean, got '$cloud_init_profile'" ;;
esac
if [[ -n "$port" ]]; then
  [[ "$port" =~ ^[0-9]+$ ]] || die "--port must be a positive integer, got '$port'"
  ((${#port} <= 5)) || die "--port out of range: '$port'"
  ((port >= 1024 && port <= 65535)) || die "--port must be between 1024 and 65535, got '$port'"
fi

# ---------------------------------------------------------------------------
# host tool resolution and fail-closed preflight
# ---------------------------------------------------------------------------

tool_hint() {
  cat >&2 <<'EOF'
lab: hint: run this command inside the development shell, which provides
lab:   qemu, cloud-utils (cloud-localds), openssh, jq and xorriso:
lab:   devenv shell -- scripts/vm/lab.sh <command> [options]
lab: on a bare Nix host you can prepend the tool directories instead:
lab:   export VM_LAB_TOOL_PATH=/nix/store/<qemu>/bin:/nix/store/<libisoburn>/bin
lab: no sudo, libvirt, host bridges or host rootful Podman are used by this lab.
EOF
}

maybe_augment_path() {
  # Last-resort convenience for this host: an explicit list of tool bin
  # directories, not a hard-coded store path. The devenv shell is the
  # supported path; this is an escape hatch for a bare Nix host.
  if [[ -n "${VM_LAB_TOOL_PATH:-}" ]]; then
    PATH="$VM_LAB_TOOL_PATH:$PATH"
    export PATH
    hash -r
  fi
}

have() { command -v "$1" >/dev/null 2>&1; }

require_tools() {
  # require_tools <preflight-label> <tool>...
  local label="$1"
  shift
  local missing=() tool
  for tool in "$@"; do
    have "$tool" || missing+=("$tool")
  done
  if ((${#missing[@]} > 0)); then
    printf 'lab: error: %s is missing required tools: %s\n' "$label" "${missing[*]}" >&2
    tool_hint
    exit 1
  fi
}

require_kvm() {
  [[ -e "$kvm_dev" ]] || {
    cat >&2 <<EOF
lab: error: $kvm_dev is missing, so hardware virtualization is unavailable.
lab: error: a native image cannot boot with KVM on this host; only a
lab: error: cross-architecture functional smoke with --accel tcg is possible.
lab: check: ls -l $kvm_dev; on a working host it is crw-rw-rw- root:kvm.
lab: fix: enable virtualization in the firmware and load the kvm kernel module.
EOF
    exit 1
  }
  [[ -r "$kvm_dev" && -w "$kvm_dev" ]] || {
    cat >&2 <<EOF
lab: error: $kvm_dev is not readable and writable by $(id -un) (uid $(id -u)).
lab: check: ls -l $kvm_dev; on this host it is world read/write and requires no sudo.
lab: fix: adjust the device permissions as a host administrator; the lab will not use sudo.
EOF
    exit 1
  }
}

require_qemu_accel_kvm() {
  # require_qemu_accel_kvm <qemu-binary>
  local qemu="$1"
  if ! "$qemu" -accel help 2>/dev/null | grep -qi 'kvm'; then
    cat >&2 <<EOF
lab: error: the $qemu on PATH has no KVM accelerator.
lab: check: $qemu -accel help (must list KVM)
lab: fix: use the qemu package from the development shell (devenv shell).
EOF
    exit 1
  fi
}

find_seed_writer() {
  # cloud-localds is the canonical NoCloud seed writer; xorriso/genisoimage
  # produce the same CIDATA volume and are a robust fallback. Returns the
  # command name on stdout or fails.
  local tool
  for tool in cloud-localds xorriso genisoimage mkisofs; do
    if have "$tool"; then
      printf '%s\n' "$tool"
      return 0
    fi
  done
  return 1
}

require_seed_writer() {
  local writer
  if ! writer="$(find_seed_writer)"; then
    cat >&2 <<'EOF'
lab: error: no cloud-init NoCloud seed writer found.
lab: error: install cloud-localds (devenv package cloud-utils) or xorriso
lab: error: (devenv package xorriso); cloud-init needs a volume labelled cidata.
EOF
    tool_hint
    exit 1
  fi
  if [[ "$writer" != "cloud-localds" ]]; then
    warn "cloud-localds is not on PATH; using '$writer' as the NoCloud seed writer fallback"
  fi
}

find_downloader() {
  local tool
  for tool in curl wget; do
    if have "$tool"; then
      printf '%s\n' "$tool"
      return 0
    fi
  done
  return 1
}

require_downloader() {
  if ! find_downloader >/dev/null; then
    cat >&2 <<'EOF'
lab: error: no downloader found; bootstrap needs curl or wget to fetch images.
lab: fix: use the development shell (devenv shell) or install curl.
EOF
    exit 1
  fi
}

preflight_bootstrap() {
  # Image download/verification never boots anything, so it must work on a
  # host without /dev/kvm or a cross-architecture qemu (the arm64 image is
  # fetched on this x86_64 host before its TCG smoke).
  maybe_augment_path
  require_tools "image bootstrap" ssh-keygen jq flock sha256sum
  require_downloader
}

preflight_image() {
  # preflight_image <image-key>: full preflight for an up/run/collect that
  # boots or reaches a VM. Resolves the image architecture to the matching
  # qemu binary and the effective accelerator before anything is created.
  local key="$1" img_arch qemu ac
  maybe_augment_path
  img_arch="$(image_arch "$key")"
  qemu="$(qemu_bin_for_arch "$img_arch")"
  require_tools "the VM lab ($img_arch)" "$qemu" qemu-img ssh ssh-keygen jq flock sha256sum
  require_seed_writer
  require_downloader
  ac="$(effective_accel "$key")"
  if [[ "$ac" == "kvm" ]]; then
    require_kvm
    require_qemu_accel_kvm "$qemu"
  else
    if [[ "$img_arch" == "$(host_arch)" ]]; then
      warn "TCG emulation forced for a native $img_arch image; it is slow and is not a performance row"
    else
      warn "cross-architecture boot: $qemu emulates $img_arch on $(host_arch) with TCG"
      warn "TCG system emulation is FUNCTIONAL SMOKE ONLY, not a performance measurement"
    fi
  fi
  if [[ "$img_arch" == "aarch64" ]]; then
    arm64_uefi="$(resolve_arm64_uefi)"
  fi
  info "image $key: arch=$img_arch accel=$ac"
}

preflight_local() {
  # Tracking/teardown must keep working even if the qemu toolchain is
  # temporarily broken, so these commands only need metadata tools.
  maybe_augment_path
  require_tools "lab state management" jq flock
}

preflight_ssh() {
  maybe_augment_path
  require_tools "guest SSH access" ssh jq
}

# ---------------------------------------------------------------------------
# image catalogue
# ---------------------------------------------------------------------------

load_images_json() {
  [[ -f "$images_json" ]] || die "missing image catalogue: $images_json"
  jq -e '.schema_version == 1 and (.images | type == "object")' "$images_json" >/dev/null 2>&1 ||
    die "invalid image catalogue (expected schema_version 1 and an images object): $images_json"
  default_image="$(jq -r '.default_image' "$images_json")"
  [[ -n "$default_image" ]] || die "image catalogue has no default_image: $images_json"
}

image_exists() {
  jq -e --arg k "$1" '.images[$k] != null' "$images_json" >/dev/null 2>&1
}

image_get() {
  # image_get <image-key> <field>; prints nothing for a null field.
  jq -r --arg k "$1" --arg f "$2" '(.images[$k] // {}) | .[$f] // empty' \
    "$images_json" 2>/dev/null || true
}

image_keys() {
  jq -r '.images | keys[]' "$images_json" 2>/dev/null || true
}

require_image() {
  local key="$1"
  image_exists "$key" || die "unknown image '$key'; known images: $(image_keys | tr '\n' ' ')"
}

host_arch() {
  case "$(uname -m)" in
    x86_64 | amd64) printf 'x86_64\n' ;;
    aarch64 | arm64) printf 'aarch64\n' ;;
    *) die "unsupported host architecture: $(uname -m) (this lab supports x86_64 and aarch64 hosts)" ;;
  esac
}

qemu_bin_for_arch() {
  # qemu_bin_for_arch <x86_64|aarch64>: the qemu-system binary that can boot
  # an image for that guest architecture (natively or under TCG).
  case "$1" in
    x86_64) printf 'qemu-system-x86_64\n' ;;
    aarch64) printf 'qemu-system-aarch64\n' ;;
    *) die "unsupported image architecture: $1 (this lab supports x86_64 and aarch64 images)" ;;
  esac
}

image_arch() {
  local key="$1" arch
  arch="$(image_get "$key" arch)"
  [[ -n "$arch" ]] || die "image '$key' has no arch in $images_json"
  printf '%s\n' "$arch"
}

effective_accel() {
  # effective_accel <image-key>: print 'kvm' or 'tcg' for the boot.
  #
  # auto is KVM exactly when the image architecture matches the host; a
  # cross-architecture image is always TCG (QEMU cannot use KVM for a
  # foreign guest) and is never presented as native. Explicit --accel kvm
  # on a foreign image is a hard error instead of a silent emulation.
  local key="$1" img_arch host ac
  img_arch="$(image_arch "$key")"
  host="$(host_arch)"
  case "$accel" in
    kvm)
      [[ "$img_arch" == "$host" ]] ||
        die "image '$key' is $img_arch but this host is $host; KVM cannot boot a foreign architecture. Use --accel tcg for a functional smoke."
      ac="kvm"
      ;;
    tcg) ac="tcg" ;;
    auto)
      if [[ "$img_arch" == "$host" ]]; then
        ac="kvm"
      else
        ac="tcg"
      fi
      ;;
    *) die "internal error: unhandled --accel '$accel'" ;;
  esac
  printf '%s\n' "$ac"
}

find_arm64_uefi() {
  # find_arm64_uefi: print the path of the AArch64 UEFI firmware to use.
  # An explicit --firmware/VM_ARM64_UEFI path wins; otherwise common distro
  # locations are tried. The lab never downloads firmware itself.
  local candidate
  if [[ -n "$arm64_uefi" ]]; then
    [[ -f "$arm64_uefi" ]] ||
      die "--firmware '$arm64_uefi' does not exist (set VM_ARM64_UEFI to a readable AAVMF_CODE.fd)"
    printf '%s\n' "$arm64_uefi"
    return 0
  fi
  for candidate in \
    "$vm_root/firmware/AAVMF_CODE.fd" \
    /usr/share/AAVMF/AAVMF_CODE.fd \
    /usr/share/AAVMF/AAVMF_CODE.no-secboot.fd \
    /usr/share/edk2/aarch64/QEMU_EFI.fd \
    /usr/share/edk2/arm/QEMU_EFI.fd \
    /usr/share/qemu-efi-aarch64/QEMU_EFI.fd \
    /usr/share/OVMF/AAVMF_CODE.fd; do
    if [[ -f "$candidate" ]]; then
      printf '%s\n' "$candidate"
      return 0
    fi
  done
  return 1
}

resolve_arm64_uefi() {
  local fw
  if fw="$(find_arm64_uefi)"; then
    printf '%s\n' "$fw"
    return 0
  fi
  cat >&2 <<EOF
lab: error: an aarch64 image needs AArch64 UEFI firmware (AAVMF) and none was found.
lab: error: place it at $vm_root/firmware/AAVMF_CODE.fd, pass
lab: error: --firmware <path>, or set VM_ARM64_UEFI.
lab: how: on Debian/Ubuntu, install qemu-efi-aarch64 and use
lab: how:   /usr/share/AAVMF/AAVMF_CODE.fd
lab: how: on a host without that package, fetch the qemu-efi-aarch64 .deb
lab: how: and extract usr/share/AAVMF/AAVMF_CODE.fd (see docs/runbooks/vm-lab.md).
lab: note: the lab writes nothing outside target/vm and never uses sudo.
EOF
  exit 1
}

# ---------------------------------------------------------------------------
# workspace layout, SSH key, image cache
# ---------------------------------------------------------------------------

ensure_layout() {
  mkdir -p "$images_dir" "$instances_dir" "$keys_dir" "$logs_dir" "$tmp_dir"
  chmod 700 "$keys_dir"
  (umask 077 && : >"$lock_file")
}

ensure_ssh_key() {
  local key="$keys_dir/id_ed25519"
  mkdir -p "$keys_dir"
  chmod 700 "$keys_dir"
  if [[ -f "$key" && -f "$key.pub" ]]; then
    info "using ephemeral SSH key target/vm/keys/id_ed25519"
  else
    rm -f "$key" "$key.pub"
    ssh-keygen -q -t ed25519 -N '' \
      -C "ebpf-fleet-vm-lab@$(hostname -s)" \
      -f "$key" >/dev/null
    info "generated ephemeral SSH key target/vm/keys/id_ed25519"
  fi
}

sha256_of() {
  local out
  out="$(sha256sum "$1")" || return 1
  printf '%s\n' "${out%% *}"
}

file_size_human() {
  local bytes
  bytes="$(stat -c %s "$1" 2>/dev/null || echo 0)"
  numfmt --to=iec-i --suffix=B "$bytes" 2>/dev/null || printf '%s bytes' "$bytes"
}

download_file() {
  local url="$1" dest="$2" tool
  tool="$(find_downloader)" || die "no curl/wget available to download $url"
  case "$tool" in
    curl)
      curl -fL --retry 3 --retry-delay 2 --connect-timeout 30 \
        -o "$dest" "$url"
      ;;
    wget)
      wget -q --show-progress -O "$dest" "$url"
      ;;
  esac
}

ensure_image() {
  # ensure_image <image-key>: verify or download the pinned base image.
  # Prints the absolute base image path on stdout. It deliberately does not
  # care about the host architecture: fetching the arm64 image on an x86_64
  # host is how the TCG functional row is prepared.
  local key="$1" url sha arch status part expected got base
  require_image "$key"
  url="$(image_get "$key" url)"
  sha="$(image_get "$key" sha256)"
  status="$(image_get "$key" status)"
  arch="$(image_get "$key" arch)"
  [[ -n "$url" ]] || die "image '$key' has no url in $images_json"
  [[ "$status" == "pinned" && -n "$sha" ]] || {
    cat >&2 <<EOF
lab: error: image '$key' is not pinned (status=${status:-unknown}, sha256=${sha:-null}).
lab: error: the lab only downloads images with a recorded sha256; it fails closed.
lab: pin it in $images_json:
EOF
    jq -r --arg k "$key" '(.images[$k] // {}) | "  url:              \(.url // "?")\n  checksum_manifest: \(.checksum_manifest // "?")\n  pin_hint:          \(.pin_hint // "use the vendor checksum manifest and record sha256")"' "$images_json" >&2 2>/dev/null || true
    exit 1
  }
  base="$images_dir/$(basename "$url")"
  if [[ -f "$base" ]]; then
    got="$(sha256_of "$base")" || die "cannot hash cached image $base"
    if [[ "$got" == "$sha" ]]; then
      info "base image $key verified (sha256 ${sha:0:12}..., $(file_size_human "$base"))"
      printf '%s\n' "$base"
      return 0
    fi
    if ((force)); then
      warn "cached base image $key hash mismatch; --force given, re-downloading"
    else
      warn "cached base image $key hash mismatch; re-downloading"
    fi
    rm -f "$base"
  fi
  mkdir -p "$images_dir" "$tmp_dir"
  part="$tmp_dir/$(basename "$url").partial"
  rm -f "$part"
  info "downloading $key from $url"
  record_event "bootstrap download image=$key url=$url"
  download_file "$url" "$part" || {
    rm -f "$part"
    die "failed to download $url"
  }
  got="$(sha256_of "$part")" || die "cannot hash downloaded image $part"
  expected="$sha"
  if [[ "$got" != "$expected" ]]; then
    rm -f "$part"
    cat >&2 <<EOF
lab: error: sha256 mismatch for $key
lab:   expected: $expected
lab:   actual:   $got
lab: the download was discarded. Re-run bootstrap; if it repeats, re-pin
lab: the image in $images_json from its checksum_manifest.
EOF
    exit 1
  fi
  mv "$part" "$base"
  chmod 644 "$base"
  info "downloaded and verified $key ($(file_size_human "$base"), sha256 ${sha:0:12}...)"
  record_event "bootstrap image-ready image=$key sha256=$sha"
  printf '%s\n' "$base"
}

# ---------------------------------------------------------------------------
# cloud-init seed
# ---------------------------------------------------------------------------

render_seed() {
  # render_seed <instance-dir> <instance-name> <image-key>
  local inst_dir="$1" vm_name="$2" image_key="$3" seed_dir instance_id pubkey template
  seed_dir="$inst_dir/seed"
  rm -rf "$seed_dir"
  mkdir -p "$seed_dir"
  pubkey="$(cat "$keys_dir/id_ed25519.pub")"
  instance_id="${vm_name}-$(date -u +%Y%m%dT%H%M%SZ)"
  # The lean profile skips the guest apt package step. It exists for TCG
  # boots (an emulated apt run costs many minutes) and still provides the
  # fleet user + key; the arm64 functional smoke only needs the base image
  # userland because the binary under test is static.
  case "$cloud_init_profile" in
    full) template="$cloud_init_dir/user-data.tmpl" ;;
    lean) template="$cloud_init_dir/user-data-lean.tmpl" ;;
    *) die "internal error: unhandled cloud-init profile '$cloud_init_profile'" ;;
  esac
  sed -e "s|__SSH_PUBKEY__|$pubkey|g" \
    -e "s|__VM_NAME__|$vm_name|g" \
    -e "s|__IMAGE_KEY__|$image_key|g" \
    "$template" >"$seed_dir/user-data"
  sed -e "s|__VM_NAME__|$vm_name|g" \
    -e "s|__INSTANCE_ID__|$instance_id|g" \
    "$cloud_init_dir/meta-data.tmpl" >"$seed_dir/meta-data"
  chmod 644 "$seed_dir/user-data" "$seed_dir/meta-data"
}

build_seed_iso() {
  # build_seed_iso <instance-dir>: prints the seed ISO path on stdout.
  local inst_dir="$1" seed_dir out tool
  seed_dir="$inst_dir/seed"
  out="$inst_dir/seed.iso"
  tool="$(find_seed_writer)" || die "no cloud-init seed writer available"
  rm -f "$out"
  case "$tool" in
    cloud-localds) cloud-localds "$out" "$seed_dir/user-data" "$seed_dir/meta-data" ;;
    xorriso)
      xorriso -as mkisofs -quiet -volid cidata -joliet -rock \
        -output "$out" "$seed_dir/user-data" "$seed_dir/meta-data" >/dev/null
      ;;
    genisoimage | mkisofs)
      "$tool" -quiet -volid cidata -joliet -rock \
        -output "$out" "$seed_dir/user-data" "$seed_dir/meta-data" >/dev/null
      ;;
    *) die "unsupported seed writer: $tool" ;;
  esac
  [[ -s "$out" ]] || die "cloud-init seed writer $tool produced an empty file: $out"
  printf '%s\n' "$out"
}

# ---------------------------------------------------------------------------
# instances
# ---------------------------------------------------------------------------

sanitize_instance_name() {
  printf '%s' "$1" | tr '.' '-'
}

resolve_instance() {
  # Sets INSTANCE_IMAGE_KEY, INSTANCE_NAME, INSTANCE_DIR. The default
  # instance name derives from the image key but dots are not valid in a
  # hostname/instance-id token, so ubuntu-24.04 becomes ubuntu-24-04.
  INSTANCE_IMAGE_KEY="${image:-$default_image}"
  if [[ -n "$name" ]]; then
    INSTANCE_NAME="$name"
  else
    INSTANCE_NAME="$(sanitize_instance_name "$INSTANCE_IMAGE_KEY")"
  fi
  validate_instance_name "$INSTANCE_NAME"
  INSTANCE_DIR="$instances_dir/$INSTANCE_NAME"
}

instance_meta() {
  # instance_meta <instance-dir> <field>
  local dir="$1" field="$2"
  [[ -f "$dir/instance.json" ]] || return 0
  jq -r --arg f "$field" 'try (.[$f] // empty) catch empty' \
    "$dir/instance.json" 2>/dev/null || true
}

instance_pid() {
  local dir="$1" pid
  pid="$(instance_meta "$dir" pid)"
  if [[ ! "$pid" =~ ^[0-9]+$ ]]; then
    pid="$(cat "$dir/qemu.pid" 2>/dev/null || true)"
  fi
  # Always succeed: callers assign this output, and an empty result must
  # not look like a failed command under `set -e`.
  [[ "$pid" =~ ^[0-9]+$ ]] && printf '%s\n' "$pid"
  return 0
}

instance_alive() {
  local dir="$1" pid args vm_name
  pid="$(instance_pid "$dir")"
  [[ -n "$pid" ]] || return 1
  kill -0 "$pid" 2>/dev/null || return 1
  vm_name="$(basename "$dir")"
  args="$(tr '\0' ' ' <"/proc/$pid/cmdline" 2>/dev/null || true)"
  [[ "$args" == *"-name $vm_name"* ]]
}

instance_port() {
  local dir="$1" p
  p="$(instance_meta "$dir" port)"
  [[ "$p" =~ ^[0-9]+$ ]] && printf '%s\n' "$p"
  return 0
}

instance_ssh() {
  # instance_ssh <instance-dir> <mode: batch|tty> <args...>
  local dir="$1" mode="$2"
  shift 2
  local p
  p="$(instance_port "$dir")" || true
  [[ -n "${p:-}" ]] || die "instance $(basename "$dir") has no recorded SSH port"
  local opts=(
    -i "$keys_dir/id_ed25519"
    -o IdentitiesOnly=yes
    -o StrictHostKeyChecking=no
    -o UserKnownHostsFile=/dev/null
    -o LogLevel=ERROR
    -p "$p"
  )
  if [[ "$mode" == "batch" ]]; then
    ssh "${opts[@]}" -o BatchMode=yes -o ConnectTimeout=5 \
      "$ssh_user@127.0.0.1" -- "$@"
  else
    ssh "${opts[@]}" -o ConnectTimeout=10 -t "$ssh_user@127.0.0.1" -- "$@"
  fi
}

port_in_use() {
  # The fd lives only in the subshell, so there is nothing to close in
  # this shell. Do not use `exec` here: an `exec` with only redirections
  # would permanently change the calling shell.
  local p="$1"
  (exec 3<>"/dev/tcp/127.0.0.1/$p") >/dev/null 2>&1
}

alloc_port() {
  local p dir used=()
  for dir in "$instances_dir"/*; do
    [[ -d "$dir" ]] || continue
    # Only running instances reserve a port; stopped instance metadata
    # keeps the last port for reference but must not block a new boot.
    instance_alive "$dir" || continue
    p="$(instance_meta "$dir" port)"
    [[ "$p" =~ ^[0-9]+$ ]] && used+=("$p")
  done
  if [[ -n "$port" ]]; then
    for p in "${used[@]}"; do
      [[ "$p" == "$port" ]] && die "port $port is already recorded for another lab instance; choose another --port"
    done
    if port_in_use "$port"; then
      die "port $port is already in use on 127.0.0.1; choose another --port"
    fi
    printf '%s\n' "$port"
    return 0
  fi
  for ((p = port_base; p <= port_max; p++)); do
    local skip=0 u
    for u in "${used[@]:-}"; do
      [[ "$u" == "$p" ]] && skip=1 && break
    done
    ((skip)) && continue
    if ! port_in_use "$p"; then
      printf '%s\n' "$p"
      return 0
    fi
  done
  die "no free SSH port in ${port_base}-${port_max}; free one or pass --port"
}

launch_vm() {
  # launch_vm <instance-dir> <base-image> <seed-iso> <ssh-port> <image-arch> <accel>
  local dir="$1" base="$2" seed="$3" p="$4" img_arch="$5" ac="$6"
  local vm_name overlay console qemu_log pid_file qemu accel_args boot_args
  vm_name="$(basename "$dir")"
  overlay="$dir/overlay.qcow2"
  console="$dir/logs/console.log"
  qemu_log="$dir/logs/qemu.log"
  pid_file="$dir/qemu.pid"
  qemu="$(qemu_bin_for_arch "$img_arch")"
  mkdir -p "$dir/logs"
  rm -f "$overlay" "$console" "$qemu_log" "$pid_file"
  qemu-img create -q -f qcow2 -F qcow2 -b "$base" "$overlay" "$disk_size"
  : >"$console"
  : >"$qemu_log"
  if [[ "$ac" == "kvm" ]]; then
    accel_args=(-accel kvm -cpu host)
  else
    # TCG has no host CPU model; 'max' is the widest emulated CPU for the
    # guest architecture and multi-threaded TCG keeps an SMP guest usable.
    accel_args=(-accel "tcg,thread=multi" -cpu max)
  fi
  local qemu_args=(
    -name "$vm_name"
    "${accel_args[@]}"
    -smp "$cpus"
    -m "$memory_mb"
  )
  if [[ "$img_arch" == "aarch64" ]]; then
    # QEMU's arm 'virt' machine has no legacy BIOS: the pinned Ubuntu arm64
    # cloud image is UEFI-bootable (GPT + EFI system partition), so boot it
    # through the AAVMF firmware resolved by preflight_image. Both disks are
    # virtio-blk-pci; the NoCloud seed is a raw ISO image on a read-only
    # virtio disk, which cloud-init scans for the cidata filesystem.
    [[ -n "$arm64_uefi" ]] || die "internal error: aarch64 boot without resolved UEFI firmware"
    qemu_args+=(
      -machine virt
      -bios "$arm64_uefi"
      -drive "file=$overlay,if=none,id=disk0,format=qcow2,cache=writeback,discard=unmap"
      -device "virtio-blk-pci,drive=disk0,bootindex=0"
      -drive "file=$seed,if=none,id=seed0,format=raw,readonly=on"
      -device "virtio-blk-pci,drive=seed0"
    )
  else
    # Keep the native x86_64 device model exactly as validated by the
    # kernel matrix rows: IDE cdrom seed + virtio system disk.
    boot_args=(-boot "order=c,menu=off")
    qemu_args+=(
      "${boot_args[@]}"
      -drive "file=$overlay,if=virtio,format=qcow2,cache=writeback,discard=unmap"
      -drive "file=$seed,media=cdrom,readonly=on"
    )
  fi
  qemu_args+=(
    -device virtio-rng-pci
    -netdev "user,id=net0,hostfwd=tcp:127.0.0.1:${p}-:22"
    -device "virtio-net-pci,netdev=net0"
    -display none
    -serial "file:${console}"
    -monitor none
    -no-reboot
    -D "$qemu_log"
    -daemonize
    -pidfile "$pid_file"
  )
  if ! "$qemu" "${qemu_args[@]}"; then
    die "QEMU failed to start instance $vm_name (see $qemu_log)"
  fi
  local i
  for ((i = 0; i < 100; i++)); do
    [[ -s "$pid_file" ]] && break
    sleep 0.05
  done
  [[ -s "$pid_file" ]] || die "QEMU did not write a pid file at $pid_file"
  printf '%s\n' "$(cat "$pid_file")"
}

write_instance_json() {
  # write_instance_json <instance-dir> <base-image> <seed-iso> <pid> <port> <image-arch> <accel>
  local dir="$1" base="$2" seed="$3" pid="$4" p="$5" img_arch="$6" ac="$7" vm_name
  vm_name="$(basename "$dir")"
  jq -n \
    --arg name "$vm_name" \
    --arg image "$INSTANCE_IMAGE_KEY" \
    --arg image_arch "$img_arch" \
    --arg accel "$ac" \
    --argjson emulated "$([[ "$ac" == "tcg" ]] && printf true || printf false)" \
    --arg cloud_init "$cloud_init_profile" \
    --argjson port "$p" \
    --argjson cpus "$cpus" \
    --argjson memory_mb "$memory_mb" \
    --arg pix "$pid" \
    --arg base "$base" \
    --arg overlay "$dir/overlay.qcow2" \
    --arg seed_iso "$seed" \
    --arg seed_dir "$dir/seed" \
    --arg ssh_user "$ssh_user" \
    --arg ssh_key "$keys_dir/id_ed25519" \
    --arg console_log "$dir/logs/console.log" \
    --arg qemu_log "$dir/logs/qemu.log" \
    --arg created_at "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
    '{
      name: $name,
      image: $image,
      image_arch: $image_arch,
      accel: $accel,
      emulated: $emulated,
      cloud_init: $cloud_init,
      port: $port,
      cpus: $cpus,
      memory_mb: $memory_mb,
      pid: ($pix | tonumber),
      base_image: $base,
      overlay: $overlay,
      seed_iso: $seed_iso,
      seed_dir: $seed_dir,
      ssh_user: $ssh_user,
      ssh_key: $ssh_key,
      console_log: $console_log,
      qemu_log: $qemu_log,
      created_at: $created_at
    }' >"$dir/instance.json"
}

boot_diagnostics() {
  local dir="$1"
  if [[ -f "$dir/logs/console.log" ]]; then
    info "last console output ($dir/logs/console.log):"
    tail -n 40 "$dir/logs/console.log" >&2 || true
  fi
  if [[ -f "$dir/logs/qemu.log" ]]; then
    info "last qemu log ($dir/logs/qemu.log):"
    tail -n 20 "$dir/logs/qemu.log" >&2 || true
  fi
}

wait_for_ssh() {
  local dir="$1" deadline
  deadline=$((SECONDS + boot_timeout))
  while ((SECONDS < deadline)); do
    if ! instance_alive "$dir"; then
      return 1
    fi
    if instance_ssh "$dir" batch true >/dev/null 2>&1; then
      return 0
    fi
    sleep 2
  done
  return 1
}

stop_instance() {
  # stop_instance <instance-dir> [purge]
  local dir="$1" want_purge="${2:-0}" vm_name pid i
  vm_name="$(basename "$dir")"
  pid="$(instance_pid "$dir")"
  if [[ -n "$pid" ]] && kill -0 "$pid" 2>/dev/null; then
    info "stopping $vm_name (pid $pid)"
    kill -TERM "$pid" 2>/dev/null || true
    for ((i = 0; i < 60; i++)); do
      kill -0 "$pid" 2>/dev/null || break
      sleep 0.25
    done
    if kill -0 "$pid" 2>/dev/null; then
      warn "QEMU did not exit after SIGTERM; sending SIGKILL to $vm_name (pid $pid)"
      kill -KILL "$pid" 2>/dev/null || true
      sleep 0.5
    fi
  else
    info "instance $vm_name is not running"
  fi
  rm -f "$dir/qemu.pid" "$dir/overlay.qcow2" "$dir/seed.iso"
  rm -rf "$dir/seed"
  if [[ -f "$dir/instance.json" ]]; then
    jq --arg now "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
      '.pid = null | .stopped_at = $now' "$dir/instance.json" \
      >"$dir/instance.json.tmp" 2>/dev/null &&
      mv "$dir/instance.json.tmp" "$dir/instance.json" 2>/dev/null || true
    rm -f "$dir/instance.json.tmp"
  fi
  if ((want_purge)); then
    rm -rf "$dir"
    info "purged instance directory $dir"
  fi
  record_event "down instance=$vm_name purge=$want_purge"
}

kill_orphan_qemus() {
  # Kill any QEMU process whose command line references this lab root.
  # Only used by down --all so a partially created instance cannot leak.
  local proc pid args killed=0
  for proc in /proc/[0-9]*; do
    pid="${proc#/proc/}"
    [[ "$pid" =~ ^[0-9]+$ ]] || continue
    [[ -r "$proc/comm" ]] || continue
    case "$(cat "$proc/comm" 2>/dev/null || true)" in
      qemu-system-*) ;;
      *) continue ;;
    esac
    args="$(tr '\0' ' ' <"$proc/cmdline" 2>/dev/null || true)"
    [[ "$args" == *"$vm_root"* ]] || continue
    warn "killing orphan QEMU process $pid ($args)"
    kill -TERM "$pid" 2>/dev/null || true
    killed=1
  done
  if ((killed)); then
    sleep 1
    for proc in /proc/[0-9]*; do
      pid="${proc#/proc/}"
      [[ -r "$proc/comm" ]] || continue
      case "$(cat "$proc/comm" 2>/dev/null || true)" in
        qemu-system-*) ;;
        *) continue ;;
      esac
      args="$(tr '\0' ' ' <"$proc/cmdline" 2>/dev/null || true)"
      [[ "$args" == *"$vm_root"* ]] || continue
      kill -KILL "$pid" 2>/dev/null || true
    done
  fi
}

# ---------------------------------------------------------------------------
# commands
# ---------------------------------------------------------------------------

cmd_bootstrap() {
  preflight_bootstrap
  load_images_json
  ensure_layout
  local keys=() key
  if ((bootstrap_all)); then
    mapfile -t keys < <(jq -r --arg arch "$(host_arch)" \
      '.images | to_entries[] | select(.value.status == "pinned") | select(.value.arch == $arch) | .key' \
      "$images_json")
    ((${#keys[@]} > 0)) || die "no pinned images for host arch $(host_arch) in $images_json"
  else
    image="${image:-$default_image}"
    require_image "$image"
    keys=("$image")
  fi
  ensure_ssh_key
  acquire_lock
  trap 'release_lock' EXIT
  for key in "${keys[@]}"; do
    local key_arch
    key_arch="$(image_arch "$key")"
    if [[ "$key_arch" != "$(host_arch)" ]]; then
      info "image $key is $key_arch; booting it later uses TCG emulation (functional smoke only)"
    fi
    ensure_image "$key" >/dev/null
  done
  release_lock
  trap - EXIT
  local fingerprint
  fingerprint="$(ssh-keygen -lf "$keys_dir/id_ed25519.pub" 2>/dev/null || true)"
  info "workspace: $vm_root"
  info "ssh key:   target/vm/keys/id_ed25519 ${fingerprint}"
  info "bootstrap complete; next: scripts/vm/lab.sh up${image:+ --image $image}"
}

cmd_up() {
  ((${#run_cmd[@]} == 0)) || die "up takes options only; guest commands belong to run"
  load_images_json
  ensure_layout
  resolve_instance
  local key="$INSTANCE_IMAGE_KEY" dir="$INSTANCE_DIR" base seed p pid
  local img_arch ac
  require_image "$key"
  preflight_image "$key"
  img_arch="$(image_arch "$key")"
  ac="$(effective_accel "$key")"
  ensure_ssh_key
  if [[ -d "$dir" ]] && instance_alive "$dir"; then
    pid="$(instance_pid "$dir")"
    die "instance $INSTANCE_NAME is already running (pid $pid); use 'scripts/vm/lab.sh down --name $INSTANCE_NAME' first, or 'status'"
  fi
  if [[ -d "$dir" ]]; then
    info "reusing instance directory $dir (stale process state is discarded)"
  fi

  acquire_lock
  trap 'release_lock' EXIT
  base="$(ensure_image "$key")"
  mkdir -p "$dir"
  p="$(alloc_port)"
  info "instance $INSTANCE_NAME: image=$key arch=$img_arch accel=$ac ssh=127.0.0.1:$p cpus=$cpus memory=${memory_mb}MiB cloud-init=$cloud_init_profile"
  render_seed "$dir" "$INSTANCE_NAME" "$key"
  seed="$(build_seed_iso "$dir")"
  local pid_new
  pid_new="$(launch_vm "$dir" "$base" "$seed" "$p" "$img_arch" "$ac")"
  if ! write_instance_json "$dir" "$base" "$seed" "$pid_new" "$p" "$img_arch" "$ac"; then
    kill -TERM "$pid_new" 2>/dev/null || true
    die "failed to write instance metadata $dir/instance.json"
  fi
  record_event "up instance=$INSTANCE_NAME image=$key arch=$img_arch accel=$ac port=$p pid=$pid_new"
  release_lock
  trap - EXIT

  info "waiting for SSH on 127.0.0.1:$p (timeout ${boot_timeout}s)"
  if ! wait_for_ssh "$dir"; then
    if ! instance_alive "$dir"; then
      warn "QEMU exited before SSH became ready"
    else
      warn "SSH did not become ready within ${boot_timeout}s"
    fi
    boot_diagnostics "$dir"
    stop_instance "$dir" 0
    die "boot failed for instance $INSTANCE_NAME; logs kept under $dir/logs"
  fi
  info "instance $INSTANCE_NAME is up:"
  info "  ssh:  scripts/vm/lab.sh ssh --name $INSTANCE_NAME"
  info "  exec: scripts/vm/lab.sh run --name $INSTANCE_NAME -- uname -r"
  info "  logs: target/vm/instances/$INSTANCE_NAME/logs/console.log"
  if [[ "$cloud_init_profile" == "full" ]]; then
    info "cloud-init may still be installing packages; it does not block SSH"
  else
    info "lean cloud-init seed: cloud-init waits for the fleet user and key only"
  fi
  if [[ "$ac" == "tcg" ]]; then
    info "TCG emulation: functional smoke only; do not use these timings for performance"
  fi
}

cmd_run() {
  ((${#run_cmd[@]} > 0)) ||
    die "run needs a guest command after --, for example: scripts/vm/lab.sh run --name <instance> -- uname -r"
  preflight_ssh
  load_images_json
  resolve_instance
  local dir="$INSTANCE_DIR"
  [[ -d "$dir" ]] || die "no instance named $INSTANCE_NAME under target/vm/instances; start one with 'scripts/vm/lab.sh up'"
  instance_alive "$dir" ||
    die "instance $INSTANCE_NAME is not running; start it with 'scripts/vm/lab.sh up --image $INSTANCE_IMAGE_KEY --name $INSTANCE_NAME'"
  instance_ssh "$dir" batch "${run_cmd[@]}"
}

# copy: stream one file between the host and a running guest over the same
# SSH path `run` uses (no scp/sftp, no extra guest packages). Binary-safe:
# batch SSH never allocates a pseudo-terminal for a remote command.
cmd_copy() {
  ((${#run_cmd[@]} == 0)) ||
    die "copy takes <source> <destination> as plain arguments, not after --"
  ((${#pos_args[@]} == 2)) ||
    die "copy needs exactly two arguments: <source> <destination> (use --from-guest to download)"
  preflight_ssh
  load_images_json
  resolve_instance
  local src="${pos_args[0]}" dst="${pos_args[1]}" dir="$INSTANCE_DIR"
  [[ -d "$dir" ]] ||
    die "no instance named $INSTANCE_NAME under target/vm/instances; start one with 'scripts/vm/lab.sh up'"
  instance_alive "$dir" ||
    die "instance $INSTANCE_NAME is not running; start it with 'scripts/vm/lab.sh up --image $INSTANCE_IMAGE_KEY --name $INSTANCE_NAME'"
  local q_src q_dst q_tmp expected got tmp
  printf -v q_src '%q' "$src"
  printf -v q_dst '%q' "$dst"
  if ((from_guest)); then
    tmp="$dst.part.$$"
    mkdir -p -- "$(dirname -- "$dst")" || die "cannot create destination directory for $dst"
    if ! instance_ssh "$dir" batch "cat -- $q_src" >"$tmp"; then
      rm -f -- "$tmp"
      die "failed to read $INSTANCE_NAME:$src (is the path readable by user $ssh_user?)"
    fi
    got="$(stat -c %s "$tmp" 2>/dev/null || echo unknown)"
    expected="$(instance_ssh "$dir" batch "wc -c < $q_src" 2>/dev/null | tr -d '[:space:]')" || expected=""
    if [[ -n "$expected" && "$got" != "$expected" ]]; then
      rm -f -- "$tmp"
      die "size mismatch downloading $INSTANCE_NAME:$src (guest $expected bytes, local $got bytes)"
    fi
    mv -f -- "$tmp" "$dst"
    info "copied $INSTANCE_NAME:$src -> $dst ($(file_size_human "$dst"))"
    return 0
  fi
  [[ -f "$src" ]] || die "local source is not a regular file: $src"
  tmp="$dst.part.$$"
  printf -v q_tmp '%q' "$tmp"
  if ! instance_ssh "$dir" batch "cat > $q_tmp && mv -f -- $q_tmp $q_dst" <"$src"; then
    instance_ssh "$dir" batch "rm -f -- $q_tmp" >/dev/null 2>&1 || true
    die "failed to write $INSTANCE_NAME:$dst (is the directory writable by user $ssh_user?)"
  fi
  expected="$(stat -c %s "$src")"
  got="$(instance_ssh "$dir" batch "wc -c < $q_dst" 2>/dev/null | tr -d '[:space:]')" || got=""
  [[ "$got" == "$expected" ]] ||
    die "size mismatch uploading to $INSTANCE_NAME:$dst (local $expected bytes, guest ${got:-unknown} bytes)"
  info "copied $src -> $INSTANCE_NAME:$dst ($(file_size_human "$src"))"
}

cmd_ssh() {
  preflight_ssh
  load_images_json
  resolve_instance
  local dir="$INSTANCE_DIR"
  [[ -d "$dir" ]] || die "no instance named $INSTANCE_NAME under target/vm/instances; start one with 'scripts/vm/lab.sh up'"
  instance_alive "$dir" ||
    die "instance $INSTANCE_NAME is not running; start it with 'scripts/vm/lab.sh up --image $INSTANCE_IMAGE_KEY --name $INSTANCE_NAME'"
  if ((${#run_cmd[@]} > 0)); then
    instance_ssh "$dir" tty "${run_cmd[@]}"
  else
    info "connecting to $INSTANCE_NAME as $ssh_user@127.0.0.1:$(instance_port "$dir")"
    instance_ssh "$dir" tty
  fi
}

cmd_down() {
  ((${#run_cmd[@]} == 0)) || die "down takes options only"
  preflight_local
  load_images_json
  local dirs=() dir
  if ((down_all)); then
    for dir in "$instances_dir"/*; do
      [[ -d "$dir" ]] && dirs+=("$dir")
    done
    ((${#dirs[@]} > 0)) || info "no instances to stop"
  else
    resolve_instance
    [[ -d "$INSTANCE_DIR" ]] || die "no instance named $INSTANCE_NAME under target/vm/instances"
    dirs=("$INSTANCE_DIR")
  fi
  if ((${#dirs[@]} > 0)); then
    acquire_lock
    trap 'release_lock' EXIT
    for dir in "${dirs[@]}"; do
      stop_instance "$dir" "$purge"
    done
    if ((down_all)); then
      kill_orphan_qemus
    fi
    release_lock
    trap - EXIT
  elif ((down_all)); then
    kill_orphan_qemus
  fi
  info "down complete"
}

cmd_status() {
  ((${#run_cmd[@]} == 0)) || die "status takes options only"
  preflight_local
  load_images_json
  local f size stamp dir state pid p image_key img_arch ac
  printf 'lab root: %s\n' "$vm_root"
  printf '\nbase images (%s):\n' "$images_dir"
  local any=0
  for f in "$images_dir"/*.img; do
    any=1
    size="$(file_size_human "$f")"
    stamp="$(date -u -r "$f" +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || true)"
    printf '  %-40s %10s  %s\n' "$(basename "$f")" "$size" "$stamp"
  done
  ((any)) || printf '  (none; run scripts/vm/lab.sh bootstrap)\n'
  printf '\ninstances (%s):\n' "$instances_dir"
  any=0
  for dir in "$instances_dir"/*; do
    [[ -d "$dir" ]] || continue
    any=1
    pid="$(instance_pid "$dir")"
    if instance_alive "$dir"; then
      state="running"
    elif [[ -n "$pid" ]]; then
      state="stale"
    else
      state="stopped"
    fi
    p="$(instance_port "$dir")"
    image_key="$(instance_meta "$dir" image)"
    img_arch="$(instance_meta "$dir" image_arch)"
    ac="$(instance_meta "$dir" accel)"
    printf '  %-24s %-8s pid=%-8s ssh=%-6s image=%s arch=%s accel=%s\n' \
      "$(basename "$dir")" "$state" "${pid:-"-"}" "${p:-"-"}" "${image_key:-"-"}" "${img_arch:-"-"}" "${ac:-"-"}"
  done
  ((any)) || printf '  (none; boot one with scripts/vm/lab.sh up)\n'
  local orphans=() proc apid args
  for proc in /proc/[0-9]*; do
    apid="${proc#/proc/}"
    [[ -r "$proc/comm" ]] || continue
    case "$(cat "$proc/comm" 2>/dev/null || true)" in
      qemu-system-*) ;;
      *) continue ;;
    esac
    args="$(tr '\0' ' ' <"$proc/cmdline" 2>/dev/null || true)"
    [[ "$args" == *"$vm_root"* ]] && orphans+=("$apid")
  done
  if ((${#orphans[@]} > 0)); then
    printf '\norphan qemu processes for this lab root: %s\n' "${orphans[*]}"
  fi
}

collect_instance() {
  local dir="$1" out="$2" vm_name p
  vm_name="$(basename "$dir")"
  mkdir -p "$out"
  local f
  for f in instance.json qemu.pid; do
    [[ -f "$dir/$f" ]] && cp "$dir/$f" "$out/" 2>/dev/null || true
  done
  for f in console.log qemu.log; do
    [[ -f "$dir/logs/$f" ]] && cp "$dir/logs/$f" "$out/" 2>/dev/null || true
  done
  if instance_alive "$dir"; then
    p="$(instance_port "$dir")"
    info "collecting guest diagnostics from $vm_name (127.0.0.1:$p)"
    instance_ssh "$dir" batch 'uname -a' >"$out/guest-uname.txt" 2>&1 || true
    instance_ssh "$dir" batch 'cat /etc/os-release' >"$out/guest-os-release.txt" 2>&1 || true
    instance_ssh "$dir" batch 'cloud-init status --long; cloud-init --version' >"$out/guest-cloud-init.txt" 2>&1 || true
    instance_ssh "$dir" batch 'ls -l /sys/kernel/btf/vmlinux 2>&1; wc -c < /sys/kernel/btf/vmlinux 2>&1' >"$out/guest-btf.txt" 2>&1 || true
    instance_ssh "$dir" batch 'id; sudo -n true && echo sudo-ok' >"$out/guest-user.txt" 2>&1 || true
    instance_ssh "$dir" batch '(sudo -n dmesg 2>/dev/null || dmesg 2>&1) | tail -n 200' >"$out/guest-dmesg.txt" 2>&1 || true
    instance_ssh "$dir" batch 'ip -br addr 2>&1; cat /proc/cmdline' >"$out/guest-network.txt" 2>&1 || true
  fi
  info "collected $vm_name -> $out"
}

cmd_collect() {
  ((${#run_cmd[@]} == 0)) || die "collect takes options only"
  preflight_local
  load_images_json
  local stamp out_root dirs=() dir
  stamp="$(date -u +%Y%m%dT%H%M%SZ)"
  out_root="$vm_root/collected/$stamp"
  if ((down_all)); then
    for dir in "$instances_dir"/*; do
      [[ -d "$dir" ]] && dirs+=("$dir")
    done
    ((${#dirs[@]} > 0)) || die "no instance directories under $instances_dir"
  else
    resolve_instance
    [[ -d "$INSTANCE_DIR" ]] || die "no instance named $INSTANCE_NAME under target/vm/instances"
    dirs=("$INSTANCE_DIR")
  fi
  mkdir -p "$out_root"
  for dir in "${dirs[@]}"; do
    collect_instance "$dir" "$out_root/$(basename "$dir")"
  done
  printf '%s\n' "$out_root"
}

# ---------------------------------------------------------------------------
# dispatch
# ---------------------------------------------------------------------------

case "$cmd" in
  bootstrap) cmd_bootstrap ;;
  up) cmd_up ;;
  run) cmd_run ;;
  ssh) cmd_ssh ;;
  down) cmd_down ;;
  status) cmd_status ;;
  collect) cmd_collect ;;
  copy) cmd_copy ;;
  *) die "internal error: unhandled command '$cmd'" ;;
esac
